APX.tn = {"country":{"name":"Tunisia","tagline":"Carthage's wine country, home of the first great agricultural writer and of Cap Bon's dry Muscat.","classification":"Tunisia has a French-style system of appellations d'origine contrôlée, with seven names registered under the Lisbon Agreement: Grand Cru Mornag, Mornag, Coteaux de Tébourba, Sidi Salem, Kélibia (Muscat de Kélibia), Thibar (Muscat de Thibar) and Coteaux d'Utique. Labels also use 'Premier Cru' for higher-quality AOC wines."},"regions":[{"name":"Bizerte and Utique","slug":"bizerte-and-utique","tagline":"","ids":["tn-coteaux-dutique"]},{"name":"Cap Bon","slug":"cap-bon","tagline":"","ids":["tn-kelibia"]},{"name":"Grand Tunis and Mornag","slug":"grand-tunis-and-mornag","tagline":"","ids":["tn-coteaux-de-tebourba","tn-grand-cru-mornag","tn-mornag","tn-sidi-salem"]},{"name":"Haut Tell (Thibar)","slug":"haut-tell-thibar","tagline":"","ids":["tn-thibar"]}],"items":{"tn-coteaux-de-tebourba":{"name":"Coteaux de Tébourba","cat":"AOC","region":"Grand Tunis and Mornag","created":"1973","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Mourvèdre","summary":"Hills along the Medjerda river west of Tunis around Tébourba, once a centre of French colonial estates. The Medjerda valley's alluvial soils and hillsides give reds and rosés from Carignan and Cinsault, and a little white wine.","rslug":"grand-tunis-and-mornag"},"tn-coteaux-dutique":{"name":"Coteaux d'Utique","cat":"AOC","region":"Bizerte and Utique","created":"1970s","styles":["red","rose"],"grapes":"Carignan, Cinsault, Grenache, Mourvèdre","summary":"Named after the Phoenician city of Utica, older than Carthage, on the lower Medjerda north-west of Tunis. Vineyards lie on low hills near the ruins of Utica and the coast of the Gulf of Tunis, giving soft reds and rosés.","rslug":"bizerte-and-utique"},"tn-grand-cru-mornag":{"name":"Grand Cru Mornag","cat":"AOC","region":"Grand Tunis and Mornag","created":"1970s","styles":["red"],"grapes":"Carignan, Grenache, Syrah, Mourvèdre, Cabernet Sauvignon","summary":"The top tier of the Mornag area, from lower-yielding hillside vineyards; 'Grand Cru' is part of the registered name. It sits at the top of the Tunisian hierarchy, and its reds are often oak-aged blends that include Syrah and Cabernet Sauvignon alongside the traditional Mediterranean grapes.","rslug":"grand-tunis-and-mornag"},"tn-kelibia":{"name":"Kélibia","cat":"AOC","region":"Cap Bon","created":"1958","styles":["white","sweet"],"grapes":"Muscat of Alexandria","summary":"Muscat de Kélibia comes from the sandy, windswept tip of Cap Bon around Kélibia, made dry and aromatic (unusually for Muscat of Alexandria) as well as sweet. Kerkouane's Punic ruins lie just north.","rslug":"cap-bon"},"tn-mornag":{"name":"Mornag","cat":"AOC","region":"Grand Tunis and Mornag","created":"1973","styles":["red","rose","white"],"grapes":"Carignan, Cinsault, Grenache, Mourvèdre, Syrah","summary":"The largest Tunisian appellation, on the plain and hills south-east of Tunis around Mornag, Khledia and the slopes of Djebel Ressas. Most of the country's reds and rosés come from here.","rslug":"grand-tunis-and-mornag"},"tn-sidi-salem":{"name":"Sidi Salem","cat":"AOC","region":"Grand Tunis and Mornag","created":"1973","styles":["red","rose"],"grapes":"Carignan, Cinsault, Grenache","summary":"A small appellation in the hinterland of Tunis; reds and rosés from Mediterranean varieties. Created in 1973 along with Mornag and Coteaux de Tébourba, it is one of the less-seen Tunisian names on export labels.","rslug":"grand-tunis-and-mornag"},"tn-thibar":{"name":"Thibar","cat":"AOC","region":"Haut Tell (Thibar)","created":"1958","styles":["sweet"],"grapes":"Muscat","summary":"Muscat de Thibar comes from the hills of Béja governorate, where the White Fathers missionaries founded a domain in 1895 and made wine and Thibarine liqueur. It is one of Tunisia's two historic Muscat appellations, both created in 1958, alongside Kélibia.","rslug":"haut-tell-thibar"}}};
